findings.program:
class Job:
    task: once fn()

fn consume(owns s: String):
    println(s)

fn main():
    s = String("payload")
    j = shares mut Job(task=fn() owns s: consume(owns s))
    k = shares mut j
    j.task()      # [CLO-6a]: "the call hands the value out of its place (the place becomes empty)"  <- breaks
    k.task()      # the emptied field, through another owner: `s` is handed over twice (double end)

class Bus:
    handlers: Array[fn()] = []
    fn click():
        for ref mut h in this.handlers:
            h()

static mut BUS: Bus = Bus()

fn main():
    BUS.handlers.push(owns fn(): BUS.handlers.clear())   # <- breaks: no real variable, no capture word
    BUS.click()        # clears the list that holds the running function: its state block is freed under it

fn names() -> Array[String]:
    return [String("ann"), String("bob")]

fn main():
    if names().first() exists as p:     # `p: ref String` views the list `names()` made, not the Option
        println(p)                      # <- by the condition sentence the list is gone; by [BRW-19] this is E3063
    # the same with `if load().shapes[0] is Circle as c:`

@derive(Copy)                 # <- E2080 asks only "if a field is not Copy"; `fd` is Copy
struct Handle:
    fd: int
    fn drop():
        close_fd(this.fd)

fn main():
    a = Handle(fd=open_fd())
    b = a                      # a copy
    # both `a` and `b` end: `drop` runs twice on one descriptor

fn check(owns s: String) -> bool:
    return s.len() > 0

fn main():
    s = String("x")
    debug_assert(check(owns s))   # <- `s` is handed over when compiling; in `release` the line runs nothing
    # `s` is never ended in release (a value without its clean-up), and W2016 speaks only of effects

class World:
    buses: Array[Bus] = []
class Bus:
    handlers: Array[fn()] = []
fn main():
    w = shares mut World()
    w.buses.push(Bus())
    w.buses[0].handlers.push(owns fn() shares mut w: w.buses.clear())   # reshapes an owner of the holding place, not the place
